// ============================================================================
// ENGLISH GRADE 7: the misconception library, part A: language and writing (part B is english-g7-mis-b.mjs).
// Written offline by Claude (13 Nov 2026). Every code starts M7_ so the Grade 4, 5, 6 and 7 maps join without a clash.
// Every entry is DRAFT: a Kenyan English teacher confirms it (source says so on each one).
// M(skill id, code, error, example question, wrong answer, right answer, help, feedback, source, cause)
// ============================================================================
import { TO_CONFIRM, KISWAHILI } from './english-g7-skills.mjs';

export const M = (skill, code, error, question, wrong, right, help, feedback, source = TO_CONFIRM, cause = 'Common error of Kenyan learners of English.') =>
  ({ skill, code, error, example: { question, wrong_answer: wrong, correct_answer: right }, cause, reveals: `Offer "${wrong}" next to the right answer in a new sentence and ask again.`, help, feedback, source });

export const MIS_A = [
  // ---- nouns: common, proper, collective, abstract
  M('NOUN_TYPES', 'M7_NT_PROPER_SMALL', 'Writes a proper noun with a small letter (kisumu, december) or a common noun with a capital.', 'We go to ___ every December.', 'kisumu', 'Kisumu', 'Names of particular places, people, days and months start with a capital letter.', 'A proper noun names one particular person, place or month, so it starts with a capital letter: Kisumu, Wanjiru, December.'),
  M('NOUN_TYPES', 'M7_NT_COLLECTIVE_WRONG', 'Uses the wrong collective noun for a group (a herd of birds, a swarm of cattle).', 'A ___ of bees settled on the tree.', 'herd', 'swarm', 'Each group has its own word: a swarm of bees, a flock of birds, a herd of cattle.', 'Each kind of group has its own collective noun: a swarm of bees, a flock of birds, a herd of cattle, a pride of lions.', TO_CONFIRM, 'Uses one word, such as group, or the word learnt first, for every group.'),
  M('NOUN_TYPES', 'M7_NT_COLLECTIVE_PLURAL', 'Thinks a collective noun is always plural (the team are winning, a flocks of birds).', 'A ___ of birds flew over the school.', 'flocks', 'flock', 'A collective noun names one group, so a flock is one thing.', 'A collective noun is one word for a whole group, so we write a flock of birds, not a flocks of birds.'),
  M('NOUN_TYPES', 'M7_NT_ABSTRACT_COMMON', 'Calls an idea or feeling a common noun for things we can touch, or the other way round.', 'Which noun is abstract: bridge, courage, bottle, drum.', 'bridge', 'courage', 'Ask: can I touch or see it? Courage is an idea.', 'An abstract noun names an idea or a feeling, such as courage, joy or freedom. A common noun for a thing, such as a bridge, can be seen or touched.'),
  M('NOUN_TYPES', 'M7_NT_COMMON_PROPER', 'Calls a name of a kind (river, city) a proper noun, or a particular name a common noun.', 'Which is a proper noun: city, Nairobi, river, teacher.', 'city', 'Nairobi', 'A proper noun is the name of one particular place or person.', 'Nairobi is the name of one particular city, so it is a proper noun. City is the word for every city, so it is a common noun.'),
  // ---- count and non-count nouns
  M('COUNT_NONCOUNT', 'M7_CN_MUCH_MANY', 'Uses much with a count noun or many with a non-count noun.', 'There were too ___ people at the gate.', 'much', 'many', 'People can be counted, so many. Water cannot, so much.', 'Use many with nouns we can count (many people) and much with nouns we cannot count (much water).'),
  M('COUNT_NONCOUNT', 'M7_CN_PLURAL_NONCOUNT', 'Adds -s to a non-count noun (advices, informations, furnitures, equipments, luggages).', 'She gave me some good ___.', 'advices', 'advice', 'Advice is one thing that is not counted: some advice, a piece of advice.', 'Advice, information, furniture, luggage and equipment are not counted, so they have no plural form. Say some advice or a piece of advice.', TO_CONFIRM, 'Many of these words have a plural form in Kiswahili or in the mother tongue.'),
  M('COUNT_NONCOUNT', 'M7_CN_FEW_LITTLE', 'Uses a few with a non-count noun or a little with a count noun.', 'Add a ___ sugar to the tea.', 'few', 'little', 'Sugar cannot be counted, so a little. Mangoes can, so a few.', 'A few goes with nouns we count (a few mangoes). A little goes with nouns we cannot count (a little sugar).'),
  M('COUNT_NONCOUNT', 'M7_CN_A_NONCOUNT', 'Puts a or an before a non-count noun (a rice, an advice).', 'Mama bought ___ rice at the market.', 'a rice', 'some rice', 'Rice is not counted one by one, so use some, not a.', 'A and an are for one thing that can be counted. For rice, water or milk say some rice or a bag of rice.'),
  // ---- plurals
  M('PLURALS', 'M7_PL_ADD_S_IRREGULAR', 'Adds -s to an irregular noun (childs, mans, tooths, foots, mouses).', 'The ___ are playing football.', 'childs', 'children', 'Some nouns change inside or have their own plural: child, children.', 'Some plurals are irregular and must be learnt: child, children; man, men; woman, women; tooth, teeth; foot, feet.'),
  M('PLURALS', 'M7_PL_Y_IES', 'Adds -s after a consonant and y (babys, storys, countrys).', 'The nurse looked after three ___.', 'babys', 'babies', 'After a consonant, y changes to ies: baby, babies.', 'When a noun ends in a consonant and y, change the y to ies: baby, babies; story, stories; country, countries.'),
  M('PLURALS', 'M7_PL_F_VES', 'Adds -s to nouns that change f or fe to ves (knifes, leafs, wolfs, lifes).', 'We cut the meat with two sharp ___.', 'knifes', 'knives', 'Say the plural aloud: knives has a v sound.', 'Some nouns that end in f or fe change to -ves in the plural: knife, knives; leaf, leaves; wolf, wolves; life, lives.'),
  M('PLURALS', 'M7_PL_SAME_FORM', 'Adds -s to a noun that stays the same in the plural (sheeps, fishs, deers).', 'Our uncle keeps twenty ___ in the village.', 'sheeps', 'sheep', 'Sheep, deer and fish do not change in the plural.', 'Some nouns have the same form in the singular and the plural: one sheep, ten sheep; one deer, two deer.'),
  M('PLURALS', 'M7_PL_ES', 'Adds only -s after s, x, ch, sh (boxs, buss, churchs, dishs).', 'Mother washed all the ___.', 'dishs', 'dishes', 'After sh, ch, s and x add -es so that the ending can be said.', 'Nouns that end in s, x, ch or sh add -es in the plural: box, boxes; bus, buses; church, churches; dish, dishes.'),
  // ---- regular and irregular verbs
  M('IRREGULAR_VERBS', 'M7_IV_ED_ON_IRREGULAR', 'Adds -ed to an irregular verb (goed, eated, buyed, thinked).', 'Yesterday we ___ to the lake.', 'goed', 'went', 'Go is an irregular verb. Its past is went.', 'Irregular verbs do not take -ed. The past of go is went, of eat is ate, of buy is bought and of think is thought.'),
  M('IRREGULAR_VERBS', 'M7_IV_PARTICIPLE_PAST', 'Uses the past form where the past participle is needed (has went, have saw, had ate).', 'The bell has already ___.', 'rang', 'rung', 'After has, have or had, use the past participle: has rung.', 'After has, have and had use the past participle: has gone, have seen, had eaten. The past form (went, saw, ate) is used alone.'),
  M('IRREGULAR_VERBS', 'M7_IV_PAST_PARTICIPLE', 'Uses the participle for the plain past (I seen it, she done it, we gone home).', 'I ___ the lion yesterday.', 'seen', 'saw', 'Without has, have or had, use the past form: I saw.', 'Used alone, the verb takes its past form: I saw, she did, we went. The participle (seen, done, gone) needs has, have or had in front of it.'),
  M('IRREGULAR_VERBS', 'M7_IV_REGULAR_IRREGULAR', 'Makes a regular verb irregular or an irregular verb regular (runned, swimmed, but wented).', 'Our teacher ___ us a story last week.', 'telled', 'told', 'Tell is irregular: told.', 'The past of tell is told, of teach is taught, of bring is brought. Regular verbs such as walk and cook take -ed.'),
  // ---- choosing the tense
  M('TENSE_CHOICE', 'M7_TC_PRESENT_FOR_PAST', 'Uses the present with a past time word (Yesterday I go to the market).', 'Yesterday, Atieno ___ to the market.', 'goes', 'went', 'Yesterday is past time, so the verb is in the past.', 'A time word such as yesterday or last week shows the past, so the verb must be in the past tense.'),
  M('TENSE_CHOICE', 'M7_TC_PAST_FOR_FUTURE', 'Uses the past with a future time word (Tomorrow we went to Mombasa).', 'Tomorrow we ___ to Mombasa.', 'went', 'will go', 'Tomorrow has not happened, so the verb is in the future.', 'A time word such as tomorrow or next week shows the future, so use will + the plain verb.'),
  M('TENSE_CHOICE', 'M7_TC_WILL_PAST', 'Uses will with a past form (will went, will came).', 'Next week our class ___ a trip.', 'will took', 'will take', 'After will, the plain verb is used: will take.', 'After will, use the plain verb, without -s, -ed or the past form: will take, will go, will come.'),
  M('TENSE_CHOICE', 'M7_TC_HABIT_PRESENT_CONT', 'Uses the continuous for a habit (She is going to church every Sunday).', 'Every Sunday, Mama ___ to church.', 'is going', 'goes', 'A habit that happens again and again uses the simple present.', 'For something that happens again and again, with words such as every day or always, use the simple present: She goes.'),
  // ---- simple present
  M('SIMPLE_PRESENT', 'M7_SP_NO_S', 'Leaves out -s after he, she, it or a single name (She walk to school).', 'Wanjiru ___ to school every day.', 'walk', 'walks', 'One person (she, he, it) takes -s or -es on the verb in the simple present.', 'In the simple present, a verb after he, she, it or one name ends in -s or -es: she walks, he washes.'),
  M('SIMPLE_PRESENT', 'M7_SP_S_PLURAL', 'Adds -s after I, you, we or they (They plays, we likes).', 'The boys ___ football after lessons.', 'plays', 'play', 'With a plural subject the verb has no -s.', 'With I, you, we, they and plural nouns the verb stays plain: the boys play.'),
  M('SIMPLE_PRESENT', 'M7_SP_DOES_S', 'Adds -s to the verb after does (She does not walks).', 'My brother does not ___ coffee.', 'drinks', 'drink', 'After do or does the plain verb is used: does not drink.', 'After do not and does not the verb is plain, because does already carries the -s: He does not drink.'),
  M('SIMPLE_PRESENT', 'M7_SP_DO_THIRD', 'Uses do not after he, she or it (She do not know).', 'Our neighbour ___ not own a car.', 'do', 'does', 'One person takes does, not do.', 'After he, she, it or one name, use does not (not do not): She does not know.'),
  M('SIMPLE_PRESENT', 'M7_SP_ES', 'Adds only -s after ch, sh, s, x, o, or y after a consonant (she washs, he trys).', 'The cook ___ the dishes after supper.', 'washs', 'washes', 'After sh, ch, s, x and o, add -es. After a consonant and y, y becomes ies.', 'Verbs that end in sh, ch, s, x or o add -es (washes, teaches, goes). A consonant and y change to ies (try, tries).'),
  // ---- simple past
  M('SIMPLE_PAST', 'M7_SPA_DID_PAST', 'Puts the past form after did (Did you went? She did not came).', 'Did you ___ the match yesterday?', 'watched', 'watch', 'Did already shows the past, so the verb is plain.', 'After did and did not, use the plain verb: Did you watch? She did not come. Did already shows the past.'),
  M('SIMPLE_PAST', 'M7_SPA_NO_ED', 'Leaves the verb plain in a past story (Yesterday she walk home).', 'Last Saturday we ___ the maize.', 'harvest', 'harvested', 'Last Saturday is past. A regular verb adds -ed.', 'A regular verb in the past ends in -ed: harvested, walked, cooked.'),
  M('SIMPLE_PAST', 'M7_SPA_SPELL_ED', 'Spells -ed wrongly (stoped, studyed, plaied).', 'The driver ___ at the junction.', 'stoped', 'stopped', 'A short verb with one vowel and one consonant doubles the last letter before -ed.', 'Spelling changes before -ed: stop, stopped (double the p); study, studied (y becomes i); play, played (no change after a vowel).'),
  M('SIMPLE_PAST', 'M7_SPA_WAS_WERE', 'Uses was with you, we or they, or were with I, he, she, it (We was late).', 'The children ___ happy to see the visitors.', 'was', 'were', 'A plural subject takes were.', 'Was goes with I, he, she, it and one name. Were goes with you, we, they and plural nouns.'),
  // ---- adjective degrees
  M('ADJECTIVE_DEGREES', 'M7_AD_MORE_ER', 'Uses more with -er (more taller) or most with -est (most tallest).', 'Kamau is ___ than his brother.', 'more taller', 'taller', 'A short adjective takes -er, with no more.', 'A short adjective takes -er or -est on its own: taller, tallest. Do not add more or most as well.'),
  M('ADJECTIVE_DEGREES', 'M7_AD_LONG_ER', 'Adds -er or -est to a long adjective (beautifuler, expensivest).', 'This dress is ___ than that one.', 'beautifuler', 'more beautiful', 'A long adjective takes more and most.', 'Long adjectives (beautiful, expensive, interesting) take more and most, not -er and -est.'),
  M('ADJECTIVE_DEGREES', 'M7_AD_IRREGULAR', 'Makes the wrong form of good, bad or far (gooder, badder, the goodest).', 'Her marks are ___ than mine.', 'gooder', 'better', 'Good is irregular: good, better, best.', 'Good, bad and far are irregular: good, better, best; bad, worse, worst; far, farther, farthest.'),
  M('ADJECTIVE_DEGREES', 'M7_AD_THAN_THE', 'Uses the with the comparative or than with the superlative.', 'Mount Kenya is the ___ mountain in Kenya.', 'higher', 'highest', 'The goes with the superlative. Than goes with the comparative.', 'The superlative (highest) is used with the for one out of many. The comparative (higher) is used with than for two.'),
  M('ADJECTIVE_DEGREES', 'M7_AD_SPELL_ER', 'Spells the -er or -est form wrongly (bigger written biger, happier written happyer).', 'Today is ___ than yesterday. (hot)', 'hoter', 'hotter', 'A short adjective with one vowel and one consonant doubles the last letter.', 'Double the last letter of a short adjective (big, bigger; hot, hotter) and change y to i (happy, happier).'),
  // ---- adverbs: kinds
  M('ADVERB_KINDS', 'M7_AK_TIME_MANNER', 'Calls an adverb of time an adverb of manner, or the other way round.', 'In "She arrived yesterday", what does yesterday tell us.', 'how', 'when', 'Ask: when, where or how? Yesterday answers when.', 'An adverb of time tells when (yesterday, soon, later). An adverb of manner tells how (slowly, carefully).'),
  M('ADVERB_KINDS', 'M7_AK_PLACE_TIME', 'Calls an adverb of place an adverb of time (here, outside).', 'In "The children played outside", what does outside tell us.', 'when', 'where', 'Outside tells where the children played.', 'An adverb of place tells where something happens (here, there, outside, nearby).'),
  M('ADVERB_KINDS', 'M7_AK_ADJECTIVE_ADVERB', 'Names an adjective or a noun as the adverb of the sentence.', 'Find the adverb: "The old man walked slowly."', 'old', 'slowly', 'An adverb tells about the verb. Slowly tells how he walked.', 'An adverb tells more about a verb. In this sentence slowly tells how the man walked. Old describes the man, so it is an adjective.'),
  M('ADVERB_KINDS', 'M7_AK_MANNER_PLACE', 'Calls a word that tells how an adverb of place, because it comes after the verb.', 'In "He answered politely", what does politely tell us.', 'where', 'how', 'Politely tells how he answered.', 'An adverb of manner tells how an action is done: politely, loudly, carefully, quickly.'),
  // ---- adverbs: forms
  M('ADVERB_FORM', 'M7_AF_GOOD_WELL', 'Uses good as an adverb (She sings good).', 'Achieng sings very ___.', 'good', 'well', 'Good describes a noun. Well describes how someone does something.', 'Good is an adjective (a good singer). Well is the adverb (she sings well).'),
  M('ADVERB_FORM', 'M7_AF_FASTLY', 'Adds -ly to fast, hard or late (fastly, lately for late).', 'The matatu was going very ___.', 'fastly', 'fast', 'Fast is both an adjective and an adverb.', 'Fast, hard and late are adverbs without -ly: He ran fast. She worked hard. Lately means recently.'),
  M('ADVERB_FORM', 'M7_AF_HARDLY', 'Uses hardly for hard (She studies hardly).', 'Njoroge studied ___ for the examination.', 'hardly', 'hard', 'Hardly means almost not at all. Hard means with a lot of effort.', 'Hard means with great effort. Hardly means almost not: He hardly slept means he slept very little.'),
  M('ADVERB_FORM', 'M7_AF_ADJECTIVE_AFTER_VERB', 'Uses an adjective after an action verb (He spoke quiet, she walks slow).', 'The teacher spoke ___ to the class.', 'quiet', 'quietly', 'An action verb is described by an adverb.', 'To tell how an action is done, use an adverb (quietly), not the adjective (quiet).'),
  M('ADVERB_FORM', 'M7_AF_SPELL_LY', 'Spells the -ly form wrongly (happyly, easyly, truely).', 'The boy answered the question ___. (easy)', 'easyly', 'easily', 'After a consonant, y changes to i before -ly.', 'Adjectives that end in y change y to i before -ly: easy, easily; happy, happily.'),
  // ---- personal pronouns
  M('PERSONAL_PRONOUNS', 'M7_PP_OBJECT_SUBJECT', 'Uses the object form as the subject (Me and Juma went; Him is tall).', '___ and Juma went to the river.', 'Me', 'I', 'Before a verb, the subject form is used: I went.', 'The subject of a sentence takes I, he, she, we or they. Me, him, her, us and them are for after a verb or preposition.'),
  M('PERSONAL_PRONOUNS', 'M7_PP_SUBJECT_OBJECT', 'Uses the subject form as the object (Give the book to I; she saw he).', 'The teacher gave the prize to Atieno and ___.', 'I', 'me', 'After to and other prepositions, the object form is used: to me.', 'After a verb or a preposition use the object form: me, him, her, us, them. So: to Atieno and me.'),
  M('PERSONAL_PRONOUNS', 'M7_PP_US_WE', 'Uses us as a subject or we as an object (Us are going; give it to we).', 'The headteacher thanked ___ for the clean compound.', 'we', 'us', 'Thanked needs an object: us.', 'We is the subject form (We cleaned). Us is the object form (She thanked us).'),
  M('PERSONAL_PRONOUNS', 'M7_PP_NUMBER', 'Uses the wrong pronoun for number or gender (the girls ... he, the tree ... she).', 'Wanjiru has a younger brother. ___ is in Grade 3.', 'She', 'He', 'The brother is a boy, so he.', 'A pronoun replaces the noun, so it must fit it: a boy is he, a girl is she, more than one is they and a thing is it.', TO_CONFIRM, 'In Kiswahili one pronoun serves he and she.'),
  M('PERSONAL_PRONOUNS', 'M7_PP_DOUBLE_SUBJECT', 'Repeats the subject with a pronoun (My mother she is a nurse).', 'Which sentence is correct.', 'My mother she is a nurse.', 'My mother is a nurse.', 'Name the person once. The noun is the subject, so no pronoun is added.', 'Do not add a pronoun after the noun that is already the subject: My mother is a nurse.'),
  // ---- possessives
  M('POSSESSIVES', 'M7_PO_ITS_ITS', 'Writes it\'s for belonging, or its for it is.', 'The dog wagged ___ tail.', 'it\'s', 'its', 'It\'s means it is. Belonging has no apostrophe: its tail.', 'Its (no apostrophe) shows belonging: its tail. It\'s is short for it is or it has.'),
  M('POSSESSIVES', 'M7_PO_APOSTROPHE_PRONOUN', 'Writes her\'s, your\'s, their\'s or our\'s.', 'This book is ___.', 'her\'s', 'hers', 'Possessive pronouns never take an apostrophe.', 'Hers, yours, ours, theirs and its never have an apostrophe.'),
  M('POSSESSIVES', 'M7_PO_MINE_MY', 'Uses mine before a noun or my where nothing follows (This is my. That is mine book).', 'Is this your pencil? Yes, it is ___.', 'my', 'mine', 'When no noun follows, use mine.', 'My, your, his, her, our and their come before a noun (my book). Mine, yours, his, hers, ours and theirs stand alone (the book is mine).'),
  M('POSSESSIVES', 'M7_PO_SUBJECT_FOR_POSSESSIVE', 'Uses a subject pronoun to show belonging (Me book, he bag, they teacher).', 'The boys left ___ bags in the classroom.', 'they', 'their', 'Belonging before a noun uses their.', 'To show who owns something, use a possessive: my, your, his, her, its, our, their.'),
  M('POSSESSIVES', 'M7_PO_THEIR_THERE', 'Mixes up their, there and they\'re.', 'The girls took ___ lunch to the field.', 'there', 'their', 'Their shows belonging. There shows a place.', 'Their shows that something belongs to them. There is a place. They\'re is short for they are.'),
  // ---- prepositions
  M('PREPOSITIONS', 'M7_PR_AT_ON_IN_TIME', 'Chooses the wrong one of at, on and in for a time (at Monday, in 5 o\'clock).', 'The meeting starts ___ Monday.', 'at', 'on', 'On for days, at for clock times, in for months and years.', 'Use on with days and dates (on Monday), at with clock times and points (at five o\'clock) and in with months, years and parts of the day (in March, in the morning).'),
  M('PREPOSITIONS', 'M7_PR_TO_IN_PLACE', 'Uses to where in is needed, or in where to is needed (She is going in school, he is to Nairobi).', 'We are going ___ the market.', 'in', 'to', 'To shows the direction of movement.', 'To shows a movement towards a place (go to the market). In shows where something already is (in the market).'),
  M('PREPOSITIONS', 'M7_PR_KIND', 'Names a preposition of place as one of time or direction.', 'In "The cat is under the table", what does under tell us.', 'time', 'place', 'Under tells where the cat is.', 'A preposition of place shows where something is (under, beside, behind, between). A preposition of direction shows movement (to, into, across).'),
  M('PREPOSITIONS', 'M7_PR_ON_AT_PLACE', 'Uses on where at is needed for a place (on the bus stop, in the gate).', 'Please wait for me ___ the bus stop.', 'on', 'at', 'At is for a point or a place we wait at.', 'At shows a point or a place where something happens (at the bus stop, at the gate, at school). On shows a surface (on the table).'),
  // ---- and, but, or
  M('CONJUNCTIONS_BASIC', 'M7_CB_AND_BUT', 'Uses and where but is needed (She is small and strong).', 'Njeri is small ___ very strong.', 'and', 'but', 'But shows that the two ideas do not go together as expected.', 'But joins ideas that contrast. And simply adds. Small is expected to go with weak, so but fits.'),
  M('CONJUNCTIONS_BASIC', 'M7_CB_OR_AND', 'Uses or where and is needed, or and where or is needed.', 'Would you like tea ___ coffee?', 'and', 'or', 'A choice is joined by or.', 'Or joins choices (tea or coffee). And joins things that go together (tea and bread).'),
  M('CONJUNCTIONS_BASIC', 'M7_CB_BUT_AND_DOUBLE', 'Uses two joining words together (But and, and but, or but).', 'He was tired ___ he finished the work.', 'but and', 'but', 'One joining word is enough between two parts.', 'Use only one joining word between two parts of a sentence. But and and, or but and or together are wrong.'),
  M('CONJUNCTIONS_BASIC', 'M7_CB_COMMA_JOIN', 'Joins two sentences with only a comma (It was late, we went home).', 'Which sentence is correct.', 'It was late, we went home.', 'It was late, so we went home.', 'A comma alone cannot join two sentences; add a joining word.', 'A comma alone cannot join two complete sentences. Add a joining word (and, but, so) or start a new sentence.'),
  // ---- articles
  M('ARTICLES', 'M7_AR_A_AN_SOUND', 'Chooses a or an by the letter, not the sound (an university, a hour).', 'Our teacher stayed for ___ hour after school.', 'a', 'an', 'Say the word: hour starts with a vowel sound, so an.', 'Choose an before a vowel sound (an hour, an egg, an umbrella) and a before a consonant sound (a university, a uniform, a house).'),
  M('ARTICLES', 'M7_AR_A_BEFORE_VOWEL', 'Uses a before a vowel (a apple, a orange).', 'She ate ___ orange after lunch.', 'a', 'an', 'Orange starts with a vowel sound, so an.', 'Use an before a word that starts with a vowel sound: an apple, an orange, an elephant.'),
  M('ARTICLES', 'M7_AR_THE_GENERAL', 'Uses the before a general idea or plural (The life is hard; I like the mangoes).', 'We should protect ___ environment.', 'a', 'the', 'The environment around us is one known thing, so the.', 'Use the for one particular or known thing (the sun, the environment). Use a or an for one of many.'),
  M('ARTICLES', 'M7_AR_NO_ARTICLE', 'Leaves out a, an or the where one is needed (She is teacher).', 'My aunt is ___ nurse at the hospital.', 'no word', 'a', 'A job needs a: a nurse.', 'A singular noun that can be counted needs a, an or the before it: She is a nurse.'),
  M('ARTICLES', 'M7_AR_FIRST_MENTION', 'Uses the for the first mention and a for the second.', 'A boy found a purse. ___ boy gave it to the teacher.', 'A', 'The', 'The boy is the one already mentioned.', 'Use a or an the first time (a boy). Use the when the same thing is mentioned again (the boy).'),
  // ---- forming adjectives
  M('ADJECTIVE_FORMATION', 'M7_AF2_NOUN_FOR_ADJ', 'Uses the noun where the adjective is needed (a danger road, a beauty girl).', 'It is a ___ road at night.', 'danger', 'dangerous', 'Before a noun, an adjective is needed: dangerous.', 'An adjective describes a noun. The adjective of danger is dangerous. We do not say a danger road.'),
  M('ADJECTIVE_FORMATION', 'M7_AF2_WRONG_SUFFIX', 'Adds the wrong ending (carely, helpness, hopeable).', 'The nurse was very ___ with the baby. (care)', 'carely', 'careful', 'Careful means full of care.', 'Add -ful for full of (careful, helpful) and -less for without (careless, hopeless). The ending must fit the word.'),
  M('ADJECTIVE_FORMATION', 'M7_AF2_SPELL_CHANGE', 'Keeps the spelling of the noun (beautyful, easyer, fameous).', 'The young girl was very ___.', 'beautyful', 'beautiful', 'Y changes to i before -ful: beauty, beautiful.', 'The spelling changes: beauty becomes beautiful (y to i), fame becomes famous (the e drops), mud becomes muddy (the d doubles).'),
  M('ADJECTIVE_FORMATION', 'M7_AF2_FUL_LESS', 'Mixes up -ful and -less (a harmful medicine used for a harmless one).', 'The old knife is ___ because it cannot cut. (use)', 'useful', 'useless', 'Cannot cut means without use: useless.', '-Ful means full of (useful, hopeful) and -less means without (useless, hopeless).'),
  // ---- phrasal verbs with put, come, give
  M('PHRASAL_PCG', 'M7_PV_PUT_OFF_OUT', 'Mixes up put off, put out and put on.', 'The firefighters ___ the fire in the market.', 'put off', 'put out', 'Put out means to stop a fire. Put off means to delay.', 'Put out means to stop a fire or a light. Put off means to delay. Put on means to wear.'),
  M('PHRASAL_PCG', 'M7_PV_GIVE_UP_IN', 'Mixes up give up, give in and give away.', 'The thief refused to ___ and run away.', 'give away', 'give up', 'Give up means to stop trying. Give away means to give for free.', 'Give up means to stop trying. Give in means to agree after refusing. Give away means to give something for free.'),
  M('PHRASAL_PCG', 'M7_PV_COME_ACROSS', 'Reads the phrasal verb word for word (come across means to cross).', 'While cleaning, Ouma ___ an old photograph.', 'came out', 'came across', 'Come across means to find by chance.', 'Come across means to find or meet by chance. Come up with means to think of. The meaning is not the sum of the words.'),
  M('PHRASAL_PCG', 'M7_PV_WRONG_PARTICLE', 'Uses the wrong little word (come out with an idea for come up with an idea).', 'The class tried to ___ a good name for the club.', 'come out with', 'come up with', 'Come up with means to think of something.', 'Come up with an idea, a plan or a name means to think of one. The particle cannot be changed.'),
  M('PHRASAL_PCG', 'M7_PV_LITERAL_PUT', 'Reads put on as put something on top (put on a jacket as place a jacket).', 'It was cold, so Baraka ___ his jacket.', 'put out', 'put on', 'Put on means to wear.', 'Put on means to wear or to switch on. Put out means to stop a fire.'),
  // ---- simple sentences
  M('SIMPLE_SENTENCE', 'M7_SS_FRAGMENT', 'Takes a group of words with no verb or no subject for a sentence (The tall girl from Kisumu).', 'Which is a complete simple sentence.', 'The tall girl from Kisumu.', 'The tall girl comes from Kisumu.', 'A sentence needs a subject and a verb and a complete thought.', 'A simple sentence needs a subject and a verb and tells a complete thought. A group of words with no verb is a fragment.'),
  M('SIMPLE_SENTENCE', 'M7_SS_COMPOUND', 'Calls a sentence with and, but or so a simple sentence.', 'Which is a simple sentence.', 'Kamau ran fast, but he lost the race.', 'Kamau lost the race.', 'A simple sentence has one subject and one verb idea.', 'A simple sentence has one main clause. A sentence joined with and, but or so has two and is a compound sentence.'),
  M('SIMPLE_SENTENCE', 'M7_SS_RUN_ON', 'Writes two sentences as one with no joining word or full stop (We arrived it was dark).', 'Which sentence is correct.', 'We arrived it was dark.', 'We arrived. It was dark.', 'Each complete thought needs its own sentence.', 'Two complete thoughts need a full stop or a joining word between them.'),
  // ---- subject-verb agreement
  M('SV_AGREEMENT', 'M7_SVA_NEAR_NOUN', 'Makes the verb agree with the noun beside it, not the subject (The box of mangoes are heavy).', 'The basket of mangoes ___ heavy.', 'are', 'is', 'The subject is the basket, one thing.', 'The verb agrees with the subject (the basket), not the noun near it (mangoes). So: The basket of mangoes is heavy.'),
  M('SV_AGREEMENT', 'M7_SVA_PLURAL', 'Uses a singular verb with a plural subject (The boys plays).', 'The boys ___ in the field.', 'plays', 'play', 'More than one boy takes the plain verb.', 'A plural subject takes a plural verb: The boys play. The girls were.'),
  M('SV_AGREEMENT', 'M7_SVA_SINGULAR', 'Uses a plural verb with a singular subject (My sister like music).', 'My sister ___ music.', 'like', 'likes', 'One sister takes likes.', 'A singular subject takes the singular verb: My sister likes. The teacher has.'),
  M('SV_AGREEMENT', 'M7_SVA_AND_SUBJECT', 'Uses a singular verb after two subjects joined by and (Juma and Otieno is friends).', 'Juma and Otieno ___ good friends.', 'is', 'are', 'Two people joined by and take are.', 'Two subjects joined by and are plural, so the verb is plural: Juma and Otieno are.'),
  M('SV_AGREEMENT', 'M7_SVA_FIND_SUBJECT', 'Names the verb or the object as the subject.', 'What is the subject of "The farmer sells vegetables"', 'sells', 'farmer', 'The subject is who or what does the action.', 'The subject is who or what does the action. The verb is the action itself.'),
  M('SV_AGREEMENT', 'M7_SVA_EVERYONE', 'Uses a plural verb with everyone, each or nobody (Everyone are ready).', 'Everyone ___ ready for the trip.', 'are', 'is', 'Everyone means every one person, so is.', 'Everyone, everybody, each, nobody and someone take a singular verb: Everyone is ready.'),
  // ---- affirmative and negative sentences
  M('NEGATIVES', 'M7_NG_DOUBLE', 'Uses two negatives (I do not have no pen).', 'I do not have ___ pen.', 'no', 'a', 'One negative is enough: do not have a pen, or have no pen.', 'Use only one negative word. Say I do not have a pen, or I have no pen.'),
  M('NEGATIVES', 'M7_NG_DONT_THIRD', 'Uses don\'t after he, she or it (She don\'t like beans).', 'She ___ like beans.', 'don\'t', 'doesn\'t', 'One person takes does not.', 'After he, she, it or one name use does not or doesn\'t: She doesn\'t like beans.'),
  M('NEGATIVES', 'M7_NG_DID_PAST', 'Uses did not with the past form (She did not went).', 'He did not ___ to school yesterday.', 'went', 'go', 'After did not the plain verb is used.', 'After did not use the plain verb: She did not go. Did already shows the past.'),
  M('NEGATIVES', 'M7_NG_NOT_PLACE', 'Puts not in the wrong place (I am go not).', 'Which sentence is negative and correct.', 'She not is here.', 'She is not here.', 'Not follows is, are, was, were, can, will, or do/does/did.', 'Not comes after the helping verb: is not, can not (cannot), will not, does not.'),
  M('NEGATIVES', 'M7_NG_NO_NOT', 'Uses no where not is needed, or not where no is needed (I am no tired).', 'I am ___ tired.', 'no', 'not', 'Not goes with a verb or an adjective. No goes with a noun.', 'Use not to make a verb or adjective negative (I am not tired). Use no before a noun (I have no time).'),
  M('NEGATIVES', 'M7_NG_KIND', 'Calls a negative sentence affirmative, or the other way, when no not appears (Nobody came).', 'Which sentence is negative.', 'Everybody came.', 'Nobody came.', 'Nobody means not anybody.', 'A sentence is negative if it says that something did not happen. Nobody, nothing, never and none make a sentence negative even without not.'),

  // ============================================================ writing
  // ---- end marks
  M('END_MARKS', 'M7_EM_QMARK_STATEMENT', 'Ends a statement or a reported question with a question mark (He asked where I was going?).', 'Which sentence is correct.', 'She asked me where I was going?', 'She asked me where I was going.', 'A question mark is for the exact question, not for a sentence that tells about it.', 'A sentence that reports a question tells what was asked, so it ends with a full stop.'),
  M('END_MARKS', 'M7_EM_FULLSTOP_QUESTION', 'Ends a real question with a full stop (Where is the market.).', 'Which sentence is correct.', 'Where is the market.', 'Where is the market?', 'A sentence that asks something ends with a question mark.', 'A direct question ends with a question mark, not a full stop.'),
  M('END_MARKS', 'M7_EM_NO_EXCLAMATION', 'Uses a full stop where a strong feeling or a command needs an exclamation mark (Watch out.)', 'Which sentence is correct.', 'Watch out.', 'Watch out!', 'A shout or sudden warning takes an exclamation mark.', 'An exclamation mark shows a strong feeling or a sudden command or warning: Watch out! What a surprise!'),
  M('END_MARKS', 'M7_EM_MANY_MARKS', 'Writes several marks together (Help!!! What???).', 'Which sentence is correct.', 'Stop thief!!!', 'Stop thief!', 'One mark is enough.', 'Use only one end mark. Writing three marks is not correct in school writing.'),
  M('END_MARKS', 'M7_EM_NO_CAPITAL', 'Forgets the capital letter at the start of the next sentence after an end mark.', 'Which is correct.', 'It was late. we went home.', 'It was late. We went home.', 'A new sentence begins with a capital letter.', 'After a full stop, question mark or exclamation mark a new sentence starts with a capital letter.'),
  // ---- narrative paragraph
  M('NARRATIVE_PARAGRAPH', 'M7_NP_OPENING_EVENT', 'Chooses an event from the middle for the opening of a narrative paragraph.', 'Which sentence best opens a narrative paragraph about a school trip.', 'Suddenly the bus broke down.', 'On Friday morning our class set off for Nakuru.', 'The opening sets the scene: who, where, when.', 'A narrative paragraph opens by setting the scene (who, where and when). The events follow in order.'),
  M('NARRATIVE_PARAGRAPH', 'M7_NP_ORDER', 'Puts the events out of order.', 'Which sentence comes last in the paragraph.', 'First we ate lunch.', 'At last we reached home.', 'Look for the closing: finally, at last, in the end.', 'Events are told in the order they happened. Words such as first, then, after that and finally show the order.'),
  M('NARRATIVE_PARAGRAPH', 'M7_NP_OFF_TOPIC', 'Keeps a sentence that is about something else in the paragraph.', 'Which sentence does not belong in the paragraph.', 'My uncle sells shoes in Eldoret.', 'We paid the fare and sat down.', 'Every sentence must belong to the same story.', 'Every sentence in a narrative paragraph is part of the same story. A sentence about something else does not belong.'),
  M('NARRATIVE_PARAGRAPH', 'M7_NP_NO_CLOSING', 'Ends the paragraph in the middle of the action with no closing.', 'Which sentence best closes the paragraph.', 'Then the driver turned left.', 'We were tired but happy when we got home.', 'A closing tells how the events ended or how the people felt.', 'A narrative paragraph ends with a closing sentence that tells how it all ended or what the person felt.'),
  // ---- paragraph examples
  M('PARAGRAPH_EXAMPLES', 'M7_PE_EXAMPLE_OFF', 'Chooses an example that is about something else.', 'Topic: Our school keeps the compound clean. Which sentence gives a good example.', 'Our school has a big football field.', 'Every Friday each class sweeps its own corner.', 'An example must show the topic sentence is true.', 'An example must show that the topic sentence is true. A fact about something else does not support it.'),
  M('PARAGRAPH_EXAMPLES', 'M7_PE_REPEAT', 'Repeats the topic sentence in other words instead of giving an example.', 'Which sentence is an example.', 'Our school is very clean.', 'Last term our school won the cleanest compound prize.', 'An example gives a real case, not the same idea again.', 'An example names a real case or incident. Saying the same thing again in other words is not an example.'),
  M('PARAGRAPH_EXAMPLES', 'M7_PE_CONNECTOR', 'Chooses the wrong words to bring in an example (However, as a result, finally).', 'Which words bring in an example.', 'However', 'For example', 'For example and for instance bring in an example.', 'For example, for instance and such as bring in an example. However shows a contrast.'),
  M('PARAGRAPH_EXAMPLES', 'M7_PE_INCIDENT_GENERAL', 'Thinks a general statement is an incident.', 'Which sentence tells an incident.', 'Children like to play.', 'Yesterday a boy found a purse and took it to the teacher.', 'An incident is one thing that happened at one time.', 'An incident is one event that happened at a time and place. A general statement is not an incident.'),
  // ---- friendly letter
  M('FRIENDLY_LETTER', 'M7_FL_WRONG_CLOSING', 'Uses a formal closing in a friendly letter (Yours faithfully to a friend).', 'Which closing suits a letter to your cousin.', 'Yours faithfully', 'Your loving cousin', 'A friendly letter ends warmly: Your friend, Yours lovingly.', 'A friendly letter ends in a warm way (Your friend, Your loving cousin). Yours faithfully is for formal letters.'),
  M('FRIENDLY_LETTER', 'M7_FL_RECEIVER_ADDRESS', 'Writes the receiver\'s address at the top of a friendly letter.', 'Which address goes at the top of a friendly letter.', 'the address of the person you are writing to', 'your own address', 'A friendly letter shows where the writer lives.', 'In a friendly letter the writer\'s address and the date go at the top right. The receiver\'s address goes only on the envelope.'),
  M('FRIENDLY_LETTER', 'M7_FL_SUBJECT_LINE', 'Adds a subject line to a friendly letter.', 'Which part is NOT needed in a friendly letter.', 'a greeting', 'a subject line in capitals', 'A subject line belongs to a formal letter.', 'A friendly letter has the address, date, greeting, body, closing and name. A subject line is for formal letters.'),
  M('FRIENDLY_LETTER', 'M7_FL_GREETING', 'Starts a friendly letter with a formal greeting (Dear Sir).', 'Which greeting suits a letter to your friend Achieng.', 'Dear Sir', 'Dear Achieng,', 'Use the name of the person you know.', 'A friendly letter begins with the name of the friend: Dear Achieng. Dear Sir is for a formal letter.'),
  M('FRIENDLY_LETTER', 'M7_FL_ORDER', 'Puts the parts in the wrong order (the name before the closing).', 'Which part comes last in a friendly letter.', 'the closing', 'the writer\'s name', 'The name comes after the closing.', 'The order is: address and date, greeting, body, closing, then the writer\'s name.'),
  // ---- commonly misspelt words
  M('MISSPELT_WORDS', 'M7_MS_IE_EI', 'Mixes up ie and ei (beleive, freind, recieve).', 'My best ___ lives in Kisii.', 'freind', 'friend', 'Friend has i before e: fri-end.', 'Remember: friend (fri + end), believe (be + lie + ve). After c it is ei: receive.'),
  M('MISSPELT_WORDS', 'M7_MS_DOUBLE_LETTER', 'Doubles or fails to double a letter (adress, neccessary, begining).', 'Write your home ___ on the form.', 'adress', 'address', 'Address has two d and two s.', 'Some words have double letters: address, necessary (one c, two s), beginning, tomorrow (one m, two r).'),
  M('MISSPELT_WORDS', 'M7_MS_SILENT_LETTER', 'Leaves out a silent letter (Febuary, goverment, libary).', 'The class was born in ___.', 'Febuary', 'February', 'Say it slowly: Feb-ru-ary has an r in the middle.', 'Some letters are not clearly said but must be written: February, government (the n), library (two r).'),
  M('MISSPELT_WORDS', 'M7_MS_SOUND_SPELL', 'Spells a word as it sounds (becuase, definately, beutiful).', 'I stayed home ___ I was sick.', 'becuase', 'because', 'Break it up: be-cause.', 'Do not spell by sound alone. Because is be + cause. Beautiful is beau + ti + ful. Definitely has finite in the middle.'),
  M('MISSPELT_WORDS', 'M7_MS_HOMOPHONE_FORM', 'Writes a sound-alike word with the wrong spelling (alot, wich, wensday).', 'Our class meets on ___.', 'Wensday', 'Wednesday', 'Wednesday has a d that is not said.', 'Wednesday has a d that is not said. A lot is two words. Which has a h in the middle.'),
  // ---- writing process
  M('WRITING_PROCESS', 'M7_WP_EDIT_FIRST', 'Puts editing before drafting.', 'What do you do first when you write a composition.', 'edit it', 'plan it', 'You cannot edit what you have not written. Planning comes first.', 'The steps are: planning, drafting, revising, editing, publishing. Planning comes first because you need ideas before you write.'),
  M('WRITING_PROCESS', 'M7_WP_REVISE_EDIT', 'Mixes up revising and editing.', 'At which step do you check spelling and punctuation.', 'revising', 'editing', 'Revising changes ideas and order. Editing corrects spelling and punctuation.', 'Revising is to improve the ideas, the order and the choice of words. Editing is to correct spelling, punctuation and grammar.'),
  M('WRITING_PROCESS', 'M7_WP_DRAFT_FINAL', 'Thinks the first draft is the final copy.', 'What is a first draft.', 'the final clean copy', 'a first try that will be improved', 'A draft is a first try.', 'A first draft is a rough first version written to get ideas down. It is improved later.'),
  M('WRITING_PROCESS', 'M7_WP_PUBLISH_FIRST', 'Puts publishing in the middle.', 'Which step comes last.', 'planning', 'publishing', 'Publishing is sharing the finished work.', 'Publishing comes last: the finished piece is copied neatly and shared.'),
  // ---- narrative features
  M('NARRATIVE_FEATURES', 'M7_NF_NARRATIVE_DESCRIPTION', 'Calls a description of a place or a person a narrative.', 'Which text is a narrative.', 'The market is wide, noisy and full of colour.', 'On Saturday Achieng lost her purse in the market and had to find it.', 'A narrative tells what happened: events in order.', 'A narrative tells a story: characters, a setting and events that happen one after another.'),
  M('NARRATIVE_FEATURES', 'M7_NF_MISSING_PART', 'Does not notice what a story lacks (the problem, the setting or the ending).', 'This story has characters and a setting but no problem. What is missing.', 'a title', 'a problem or conflict', 'A story needs something to go wrong or to be solved.', 'A narrative needs a problem or a conflict, events and an ending.'),
  M('NARRATIVE_FEATURES', 'M7_NF_SETTING_CHARACTER', 'Names a character as the setting or the setting as a character.', 'What is the setting of a story.', 'the people in the story', 'the time and place of the story', 'Setting means where and when.', 'The setting is where and when the story happens. The characters are the people or animals in it.'),
  M('NARRATIVE_FEATURES', 'M7_NF_PERSON', 'Writes a narrative in the present tense, or mixes I and he in the same story.', 'Which opening is a narrative told in the past.', 'I am walking to the river.', 'I walked to the river early in the morning.', 'A story about what happened is told in the past tense.', 'A narrative about past events is told in the past tense and keeps one person (I or he, she, they) throughout.'),
  // ---- list grouping
  M('LIST_GROUPING', 'M7_LG_WRONG_GROUP', 'Puts an item under the wrong heading.', 'Which item belongs under "Food" in a packing list.', 'torch', 'bread', 'Food is for eating.', 'Group items by kind: food (bread, water, fruit), clothes (jacket, socks), tools (torch, panga).'),
  M('LIST_GROUPING', 'M7_LG_ODD_ITEM', 'Does not see which item does not belong to the group.', 'Which item does not belong with the others: pen, ruler, pencil, soap.', 'ruler', 'soap', 'Three are stationery.', 'Pen, ruler and pencil are stationery. Soap is for washing, so it belongs to a different group.'),
  M('LIST_GROUPING', 'M7_LG_EVENT_FIT', 'Chooses items that do not fit the event.', 'Which list fits a day at the beach.', 'school bag, books, ruler', 'swimming costume, towel, sunscreen', 'Think about what the event needs.', 'A packing list must fit the event: for a day at the beach, a swimming costume, a towel and sunscreen.'),
  M('LIST_GROUPING', 'M7_LG_QUANTITY', 'Leaves out the amount in a shopping list (sugar, flour, rice with no amounts).', 'Which shopping list entry is best.', 'sugar', '2 kg of sugar', 'A shopping list says how much to buy.', 'A shopping list says what and how much: 2 kg of sugar, 3 loaves of bread.'),
  // ---- synonyms and antonyms
  M('SYNONYMS_ANTONYMS', 'M7_SY_RELATED_NOT_SAME', 'Gives a related word instead of a synonym (big for huge is right, but big for building is not).', 'Which word means the same as "tiny".', 'small', 'minute', 'A synonym can replace the word.', 'A synonym has almost the same meaning and can replace the word in the sentence.'),
  M('SYNONYMS_ANTONYMS', 'M7_SY_ANT_SYN', 'Gives a synonym when an antonym is asked, or the other way round.', 'Which word is the opposite of "ancient".', 'old', 'modern', 'An antonym has the opposite meaning.', 'A synonym means the same. An antonym means the opposite: ancient and modern are antonyms; ancient and old are synonyms.'),
  M('SYNONYMS_ANTONYMS', 'M7_SY_PREFIX_ANT', 'Makes an antonym only by adding un- or not (unhot, not-big).', 'The opposite of "generous" is ___.', 'ungenerous', 'selfish', 'Not every antonym is made with un-.', 'Many antonyms are different words (generous, selfish). Do not make an opposite by adding un- to every word.'),
  M('SYNONYMS_ANTONYMS', 'M7_SY_CONTEXT', 'Chooses a synonym that does not fit the sentence.', 'Which word can replace "bright" in "She is a bright pupil".', 'shiny', 'clever', 'A word can have more than one meaning. Check which meaning fits the sentence.', 'A word may have different synonyms for different meanings. In this sentence bright means clever, not shiny.'),
  // ---- numbers in words
  M('NUMBER_WORDS', 'M7_NW_FORTY', 'Spells forty as fourty or fourteen as forteen.', 'Write 40 in words.', 'fourty', 'forty', 'Forty has no u, but four and fourteen have.', 'Four and fourteen have a u. Forty has no u. Ninety has an e before ty.'),
  M('NUMBER_WORDS', 'M7_NW_ORDINAL', 'Writes an ordinal with the wrong ending (1th, 2th, 3th, twenty-oneth).', 'Our school sports day is on the 22___ of May.', '22th', '22nd', 'Numbers ending in 2 take nd.', 'Ordinals: 1st, 2nd, 3rd, then th (4th to 20th), then 21st, 22nd, 23rd, 24th.'),
  M('NUMBER_WORDS', 'M7_NW_HYPHEN', 'Leaves out the hyphen in twenty-one to ninety-nine.', 'Write 45 in words.', 'forty five', 'forty-five', 'Join the two words with a hyphen.', 'Numbers from twenty-one to ninety-nine are written with a hyphen: twenty-one, forty-five.'),
  M('NUMBER_WORDS', 'M7_NW_EIGHTH', 'Spells the ordinal wrongly (eigth, nineth, twelvth).', 'He finished in ___ place.', 'eigth', 'eighth', 'Eighth has two h, one in eigh and one in th.', 'Spell the ordinal in words: eighth (eight + h), ninth (no e), twelfth (twelve loses the e and adds fth).'),
  M('NUMBER_WORDS', 'M7_NW_START_FIGURE', 'Begins a sentence with a figure (40 learners came).', 'Which sentence is correct.', '40 learners came to the meeting.', 'Forty learners came to the meeting.', 'Never begin a sentence with a figure.', 'A sentence must not begin with a figure. Write the number in words: Forty learners came.'),
  // ---- dialogue format
  M('DIALOGUE_FORMAT', 'M7_DF_QUOTES_EVERY_LINE', 'Writes a play-style dialogue with quotation marks round every line.', 'Which is the correct play-style dialogue.', '"Atieno: Good morning." "Juma: Good morning."', 'Atieno: Good morning.\nJuma: Good morning.', 'In a script the speaker name and a colon show who is speaking.', 'In a written dialogue (a script) the speaker\'s name and a colon begin each line. Quotation marks are for direct speech inside a story.'),
  M('DIALOGUE_FORMAT', 'M7_DF_SAME_LINE', 'Runs the speakers together on one line.', 'How should each speaker\'s words be written.', 'on the same line', 'on a new line', 'Each turn starts on a new line.', 'Each speaker\'s turn begins on a new line, so the reader sees who is speaking.'),
  M('DIALOGUE_FORMAT', 'M7_DF_ACTIONS', 'Writes actions without brackets so they look like spoken words.', 'How are actions such as smiling shown in a dialogue.', 'in quotation marks', 'in brackets after the name', 'Brackets show it is not spoken.', 'Actions and feelings are written in brackets after the speaker\'s name, for example Atieno (smiling): Good morning.'),
  M('DIALOGUE_FORMAT', 'M7_DF_NO_NAME', 'Leaves out the speaker\'s name.', 'What does each line of a dialogue start with.', 'the words spoken', 'the speaker\'s name and a colon', 'Without a name we do not know who speaks.', 'Each line begins with the name of the speaker and a colon, then what the person says.'),
  // ---- idioms
  M('IDIOMS', 'M7_ID_LITERAL', 'Reads an idiom word for word (it is raining cats and dogs means animals fall).', 'What does "it is raining cats and dogs" mean.', 'animals are falling from the sky', 'it is raining very hard', 'An idiom means more than its words.', 'An idiom has a meaning that is not the same as its words: raining cats and dogs means raining very hard.'),
  M('IDIOMS', 'M7_ID_WRONG_MEANING', 'Gives a meaning that fits one word of the idiom but not all.', 'What does "spill the beans" mean.', 'to cook a meal', 'to tell a secret', 'Think of what happens when beans spill.', 'Spill the beans means to tell a secret by mistake.'),
  M('IDIOMS', 'M7_ID_CHANGED_WORD', 'Changes a word in the idiom (a piece of pie, hit the nail on the finger).', 'Complete: It was a piece of ___. (very easy)', 'pie', 'cake', 'The words of an idiom are fixed.', 'An idiom cannot be changed: a piece of cake, not a piece of pie.'),
  // ---- descriptive writing
  M('DESCRIPTIVE_FEATURES', 'M7_DW_NARRATIVE_DESC', 'Takes a story of events for a description.', 'Which text is descriptive writing.', 'We walked to the lake and then swam.', 'The lake was calm and silver, and the air smelled of wet grass.', 'A description shows what something looks, sounds or feels like.', 'Descriptive writing paints a picture of a person, a place or a thing, using the senses. A narrative tells events.'),
  M('DESCRIPTIVE_FEATURES', 'M7_DW_FACTS_ONLY', 'Thinks listing facts is a description.', 'Which sentence is the best description.', 'The market opens at six o\'clock.', 'The market bursts with the smell of fresh bread and the shouts of sellers.', 'A description uses the senses: see, hear, smell, touch, taste.', 'A good description uses the senses and exact words, not only facts.'),
  M('DESCRIPTIVE_FEATURES', 'M7_DW_ORDER', 'Describes in a jumbled order.', 'In what order is a building usually described.', 'in any order', 'in a clear order, such as from the front to the back', 'A reader must follow where you are looking.', 'A description follows a clear order, such as top to bottom, near to far or front to back.'),
  M('DESCRIPTIVE_FEATURES', 'M7_DW_VAGUE_WORDS', 'Uses vague words such as nice and good instead of exact ones.', 'Which sentence has the best detail.', 'The food was nice.', 'The ugali was hot and soft, with a smoke-sweet smell.', 'Exact words let the reader picture it.', 'Use exact words (hot, soft, smoky) instead of vague words such as nice, good or very.'),
  // ---- notices and posters
  M('NOTICE_POSTER', 'M7_NO_MISSING_WHEN', 'Leaves out the date or time of a notice.', 'This notice has a heading, the place and the writer. What is missing: "SPORTS DAY. At the school field. Games Master."', 'a picture', 'the date and time', 'A notice must say when.', 'A notice tells what, when and where, and who to see, with the writer\'s name and the date.'),
  M('NOTICE_POSTER', 'M7_NO_POSTER_LONG', 'Writes a poster in long paragraphs.', 'Which is best for a poster.', 'a long paragraph with every detail', 'a big heading and a few short lines', 'A poster must be read at a glance.', 'A poster has a big heading, a few words, a picture and only the key details.'),
  M('NOTICE_POSTER', 'M7_NO_NOTICE_POSTER', 'Mixes up the features of a notice and a poster.', 'Which has a picture to catch the eye.', 'a notice', 'a poster', 'A poster uses a picture.', 'A poster usually has a picture and big letters to attract people. A notice gives the details briefly in words.'),
  M('NOTICE_POSTER', 'M7_NO_SIGNED', 'Forgets who wrote the notice.', 'Who signs a school notice.', 'nobody', 'the person who wrote it, with the date', 'A reader must know who to ask.', 'A notice ends with the name and title of the writer and the date.'),
];

// ---- additions found while writing the families
MIS_A.push(
  M('NOUN_TYPES', 'M7_NT_COLLECTIVE_SINGLE', 'Takes one member of the group, or the person who looks after it, for the collective noun.', 'Which noun is a collective noun.', 'player', 'team', 'A collective noun names the whole group as one.', 'A collective noun is one word for a whole group (team, herd, class, family). A player or a farmer is one member or one person.'),
  M('COUNT_NONCOUNT', 'M7_CN_COUNT_KIND', 'Calls a noun that cannot be counted a count noun, or one that can be counted a non-count noun.', 'Which noun is a non-count noun.', 'chair', 'water', 'Ask: can I say one, two, three of it?', 'A count noun can have a number before it (three chairs). A non-count noun cannot (water, milk, rice, advice).'),
  M('PLURALS', 'M7_PL_SINGULAR_KIND', 'Cannot tell the singular from the plural of an irregular noun (thinks children is singular, or that mouse is plural).', 'Which word is a plural noun.', 'child', 'children', 'Plural means more than one.', 'Children, men, women, teeth and feet are plural nouns with irregular forms. Child, man, woman, tooth and foot are singular.'),
  M('SV_AGREEMENT', 'M7_SVA_THERE_IS', 'Uses there is with a plural noun (There is three books on the table).', 'There ___ four chairs in the room.', 'is', 'are', 'Four chairs is plural, so are.', 'After there the verb agrees with the noun that follows: there is a chair, there are four chairs.'),
  M('SIMPLE_SENTENCE', 'M7_SS_NOT_SENTENCE', 'Calls two words with no verb (a list) a sentence.', 'Which is a complete simple sentence.', 'Red apples and ripe mangoes.', 'Red apples grow here.', 'Look for a verb.', 'A sentence needs a verb to say what the subject does or is.'),
);

MIS_A.push(
  M('TENSE_CHOICE', 'M7_TC_WRONG_TIME', 'Chooses a tense that does not fit the time word (a continuous or participle form where a simple tense is needed).', 'Last Saturday we ___ the maize.', 'harvesting', 'harvested', 'Match the verb to the time word.', 'The time word shows the tense: last Saturday needs the simple past, every day the simple present, next week will + the plain verb.'),
  M('SIMPLE_PRESENT', 'M7_SP_WRONG_FORM', 'Uses an -ing or a past form where the simple present is needed.', 'My sister ___ to music while she studies.', 'listening', 'listens', 'A habit uses the simple present.', 'For a habit or a fact use the simple present: she listens, they play. An -ing form needs is, are or am in front of it.'),
  M('ADJECTIVE_DEGREES', 'M7_AD_PLAIN_FORM', 'Uses the plain adjective where the comparative or the superlative is needed (Juma is tall than Peter).', 'Juma is ___ than Peter.', 'tall', 'taller', 'Than needs a comparative.', 'After than use the comparative (taller). The plain adjective (tall) is used with as ... as.'),
  M('ARTICLES', 'M7_AR_WRONG_WORD', 'Uses a word that does not go with one thing (many, these) where a, an or the is needed.', 'There was ___ egg on the table.', 'many', 'an', 'A single thing needs a, an or the.', 'Many and these go with more than one. A single thing needs a, an or the.'),
);

MIS_A.push(
  M('PARAGRAPH_EXAMPLES', 'M7_PE_KEEPS_OFF_TOPIC', 'Keeps a sentence about something else in the paragraph, or takes a sentence that belongs for the odd one.', 'Which sentence does not belong in the paragraph.', 'a sentence that belongs', 'the sentence about something else', 'Every sentence must be about the topic.', 'Every sentence of a paragraph must be about the same topic. The sentence about something else does not belong.'),
  M('NUMBER_WORDS', 'M7_NW_SPELL_NUMBER', 'Spells a number word wrongly (ninty, fourty, forteen).', 'Write 90 in words.', 'ninty', 'ninety', 'Ninety has an e before ty.', 'Say the number slowly and spell each part: nine + ty = ninety (the e stays), four + teen = fourteen, but forty has no u.'),
);

MIS_A.push(
  M('HANDWRITING', 'M7_HW_UNEVEN', 'Thinks letters of different sizes, or letters that float above the line, are fine.', 'Which is a feature of neat handwriting.', 'letters of different sizes', 'letters of an even size on the line', 'Look at the size and the line.', 'Neat handwriting has letters of an even size that sit on the line. Tall letters (b, d, h, l) are taller and short letters (a, c, e, o) are shorter, in the same way each time.'),
  M('HANDWRITING', 'M7_HW_CROWDED', 'Leaves no clear spaces between words.', 'What should there be between words in neat handwriting.', 'no space', 'a clear space', 'A reader needs to see where one word ends.', 'There is a clear space between words so that the reader can see where each word starts and ends.'),
  M('HANDWRITING', 'M7_HW_FAST', 'Thinks writing quickly or pressing hard is the way to neat writing.', 'What should Peter work on to make his handwriting easier to read.', 'write faster', 'keep the letters even and leave spaces between words', 'Neat writing is steady, not rushed.', 'Writing fast or pressing hard does not make handwriting neat. Even letters and clear spaces do.'),
  M('HANDWRITING', 'M7_HW_DECORATE', 'Thinks loops, decoration or colour make handwriting better.', 'Which handwriting is easiest to read.', 'letters with loops and decorations', 'plain, even letters on the line', 'Plain letters are easiest to read.', 'Legible handwriting is plain and clear. Decorations and unusual shapes make it harder to read.'),
  M('ASSESS_NARRATIVE', 'M7_AN_PART_MIX', 'Mixes up what the introduction, the body and the conclusion do.', 'Which part of a narrative tells who, where and when.', 'the conclusion', 'the introduction', 'The introduction opens the story and sets the scene.', 'The introduction sets the scene (who, where, when). The body tells the events in order. The conclusion ends the story.'),
  M('ASSESS_NARRATIVE', 'M7_AN_SPELLING_ONLY', 'Thinks assessing a composition is only counting words or checking spelling.', 'What is the first step when you assess your own composition.', 'count the words', 'read it again slowly', 'Assessing starts by reading with care.', 'To assess a composition, read it again slowly and check each part. Spelling is one thing to check, but not the only one.'),
  M('ASSESS_NARRATIVE', 'M7_AN_SKIP_READ', 'Hands in a composition without reading it again.', 'What should you do before you hand in your composition.', 'hand it in at once', 'read it again and check each part', 'Always read your work again.', 'Read your work again before handing it in. Reading again helps you to find what needs to be improved.'),
  M('READING_STRATEGIES', 'M7_RS_SKIM_SCAN', 'Mixes up skimming and scanning.', 'You want to find one name quickly in a long text. Which strategy is best.', 'skimming', 'scanning', 'Scanning looks for one fact. Skimming gets the general idea.', 'Skimming is reading quickly to get the general idea. Scanning is running the eye over a text to find one name, number or fact.'),
  M('READING_STRATEGIES', 'M7_RS_WRONG', 'Chooses something that is not a strategy (guessing, skipping, reading aloud every word) for the purpose.', 'You do not understand a sentence. Which strategy helps.', 'skipping it', 'reading it again with the words around it', 'A reading strategy helps you to understand.', 'Rereading the sentence and the words around it, predicting, skimming and scanning are strategies. Skipping and guessing are not.'),
  M('FLUENCY_STRATEGIES', 'M7_FL_FLAT', 'Thinks a fluent reader reads in one even voice with no feeling.', 'Which helps you to read with expression.', 'reading every word in the same flat voice', 'changing your voice to show feelings and pausing at full stops', 'Expression means the voice shows the meaning.', 'A fluent reader changes the voice to show feelings, and pauses at commas and full stops.'),
  M('FLUENCY_STRATEGIES', 'M7_FL_FAST', 'Thinks fluent reading is reading as fast as possible.', 'Which is reading at the right speed.', 'as fast as possible', 'not too fast and not too slow, so the listener can follow', 'Fluent reading can be understood.', 'The right speed is steady, so that the listener can follow. Reading too fast loses the meaning.'),
  M('FLUENCY_STRATEGIES', 'M7_FL_WORD', 'Reads one word at a time and stops at every hard word.', 'Which is a way to read more fluently.', 'stopping at every difficult word', 'reading the same short text several times', 'Fluent reading flows in groups of words.', 'A fluent reader reads words in groups and reads a text again to make it smooth. Stopping at every word breaks the flow.'),
);
